def source_graph(n):
 if n==1:
  origin=(130,205);s=22
  def pt(x,y):return(origin[0]+s*x,origin[1]-s*y)
  paths=[path([pt(y*y/8,y) for y in [i/10 for i in range(-85,86)]]),path([pt(-3,0),pt(11,0)]),path([pt(0,-8.8),pt(0,8.8)]),path([pt(-2,-8.8),pt(-2,8.8)])]
  labels=[(*pt(11.3,0),'x'),(*pt(0,9.1),'y'),(199,57,'y²=8x'),(79,138,'x=−2'),(165,243,'F(2,0)'),(105,227,'V')]
  dots=[(0,0),(-2,0),(2,0),(2,4),(2,-4),(8,8),(8,-8)]
  for x,y in [(2,4),(2,-4),(8,8),(8,-8)]:a,b=pt(x,y);labels.append((a+5,b-8 if y>0 else b+21,f'({x},{y})'))
  for x in [2,4,6,8,10]:a,b=pt(x,0);paths.append(path([(a,b-4),(a,b+4)]));labels.append((a-4,b+20,str(x)))
  for y in [-8,-6,-4,-2,2,4,6,8]:a,b=pt(0,y);paths.append(path([(a-4,b),(a+4,b)]));labels.append((a-23,b+5,str(y)))
  size=(460,440)
 else:
  origin=(250,90);s=53
  def pt(x,y):return(origin[0]+s*x,origin[1]-s*y)
  paths=[path([pt(x,-x*x) for x in [i/100 for i in range(-210,211,2)]]),path([pt(-2.6,0),pt(2.6,0)]),path([pt(0,-4.6),pt(0,1.2)]),path([pt(-2.5,.25),pt(2.5,.25)]),path([(109,155),pt(0,-.25)])]
  labels=[(*pt(2.7,0),'x'),(*pt(0,1.3),'y'),(284,53,'y=1/4'),(192,68,'V(0,0)'),(59,170,'F(0,−1/4)'),(340,252,'x²=−y')]
  dots=[(0,0),(0,-.25),(-.5,-.25),(.5,-.25),(-1,-1),(1,-1),(-2,-4),(2,-4)]
  for x,y in [(-1,-1),(1,-1),(-2,-4),(2,-4)]:a,b=pt(x,y);labels.append((a-62 if x<0 else a+5,b+21,f'({x},{y})'))
  for x in [-2,-1,1,2]:a,b=pt(x,0);paths.append(path([(a,b-4),(a,b+4)]));labels.append((a-5,b+21,str(x)))
  size=(480,390)
 return geometry('Figure 9.4' if n==1 else 'Figure 9.5','Exact source parabola, focus, directrix and listed coordinate points for Example '+str(n),paths,labels,points=[{'x':pt(x,y)[0],'y':pt(x,y)[1]} for x,y in dots],size=size)
PAGES=[page('126_page_1.jpg',243,[heading('(ii) General form of an equation of a parabola'),paragraph('To obtain the general form of the parabola, let us assume a focus with coordinates F(p,0) and a directrix x = −p, (p is any positive number) parallel to the y-axis. If P(x,y) is any point on the curve and P₁(−p,y) is a point on the directrix x = −p, then by the definition of parabola Figure 9.3:'),distance_graph(),eq(r'\frac{\mathrm{distance\ from}\ P\ \mathrm{to}\ F}{\mathrm{distance\ from}\ P\ \mathrm{to}\ P_1}=e=1,\quad\mathrm{for\ parabola}\ e=1'),paragraph('Distance from P(x,y) to P₁ = distance from P(x,y) to F:'),eq(r'd(P,P_1)=d(P,F)'),eq(r'\sqrt{(x+p)^2+0}=\sqrt{(x-p)^2+(y-0)^2}','2'),eq(r'(x+p)^2=(x-p)^2+y^2,\quad\mathrm{by\ squaring}'),eq(r'x^2+2px+p^2=x^2-2px+p^2+y^2\ \Rightarrow\ 4px=y^2','3'),paragraph('The result (3) is the standard form obtained from the general form of the equation of a parabola with vertex at V(0,0), focus F(p,0) and directrix x = −p. The parabola is symmetric with respect to the positive x-axis if p > 0 and symmetric with respect to the negative x-axis if p < 0. The vertex V(0,0) of the parabola is on the principal axis of symmetry midway between the focus and the directrix.'),
 heading('(iii) Standard equations of parabola, sketch their graphs and find their element'),heading('a. Standard equations of parabola'),paragraph('The standard form of an equation of a parabola that is symmetric with respect to the x-axis, with vertex V(0,0), focus F(p,0) and directrix the line x = −p is:'),eq(r'y^2=4px','4'),paragraph('The standard form of an equation of a parabola that is symmetric with respect to the y-axis, with vertex V(0,0), focus F(0,p) and directrix the line y = −p is:'),eq(r'x^2=4py','5'),paragraph('The parabolas that have their vertex at the origin and open upward, downward, to the left and to the right are summarized in the following table:'),{'type':'dataTable','headers':['Parabola','Curve','Focus','Directrix','Vertex'],'rows':[['x²=4py','up, if p>0','F(0,p)','y=−p','V(0,0)'],['x²=4py','down, if p<0','F(0,p)','y=−p','V(0,0)'],['y²=4px','right, if p>0','F(p,0)','x=−p','V(0,0)'],['y²=4px','left, if p<0','F(p,0)','x=−p','V(0,0)']]},heading('b. Graphing standard form of a parabola'),paragraph('Here, we will find and plot the parabola by inspection and count out units from the vertex in the appropriate direction as determined by the form of the equation. Finally, it is shown in the problem set that the length of the focal chord (latus rectum) is |4p|. This number could be used in determination of the width of the parabola. This approach is employed in the following examples.'),note('Both signs share the same entire axis of symmetry; sign p determines which direction the curve opens. The initial distance derivation assumes p > 0; extending the algebra to p < 0 gives the left-opening form, while p = 0 is degenerate. Squaring the two nonnegative distances introduces no extra points: on y² = 4px their squared distances agree and hence their actual distances agree. The latus-rectum length is 4|p|, not a signed parameter.')]),
 page('126_page_2.jpg',244,[heading('Example 1'),paragraph('Graph the parabola y²−8x = 0 and indicate the vertex, focus, directrix and the focal chord.'),heading('Solution'),paragraph('Rewrite the given parabola in the standard form y² = 8x (6) and compare with standard form (3) to obtain:'),eq(r'8=4p\ \Rightarrow\ p=2'),paragraph('Since p > 0, the parabola opens to the right. The vertex is V(0,0), the focus is F(2,0), the directrix is the line x = −2 and the length of the focal chord is 4p = 4(2) = 8. The line of symmetry is the positive x-axis. This is shown in Figure 9.4.'),source_graph(1),
 heading('Example 2'),paragraph('Graph the parabola x²+y = 0 and indicate the vertex, focus, directrix and the focal chord.'),heading('Solution'),paragraph('Rewrite the given parabola in the standard form x² = −y (7) and compare with standard form (5) to obtain:'),eq(r'-1=4p\ \Rightarrow\ p=-\frac14'),paragraph('Since p < 0, the parabola opens downward. The vertex is V(0,0), the focus is F(0,−1/4), the directrix is the line y = 1/4 and the length of the focal chord is 4p = 4(−1/4) = −1. The line of symmetry is the negative y-axis. This is shown in Figure 9.5.'),source_graph(2),note('The latus rectum in Example 2 has nonnegative length 4|p| = 1, with endpoints (−1/2,−1/4) and (1/2,−1/4). The source’s −1 is a signed 4p value, not a geometric length. Its axis of symmetry is the whole y-axis. Both native graphs use the exact source coordinate points, with true focal-chord endpoints identified in the learning solution.'),
 heading('(iv) The equation of a parabola with the given elements'),paragraph('focus and vertex; focus and directrix; vertex and directrix.'),heading('Example 3'),paragraph('Find an equation of parabola with (a) focus F(0,−2) and directrix y = 2; (b) focus F(5/8,0) and vertex (0,0); (c) vertex V(0,0) and directrix x = 1/2.'),heading('Solution'),paragraph('a. By inspection, the value of p is p = −2 that satisfies the directrix y = 2. This gives the equation of parabola x² = 4py = 4(−2)y = −8y, that opens downward (p < 0) and the line of symmetry is the negative y-axis. This is shown in Figure 9.6.')])]
